            <div class="clearfix text-formatted field field--name-body field--type-text-with-summary field--label-hidden field__item"><div class="main_content"><div class="container-fluid course-section"><!-- PROGRAM SELECTOR --><div class="row"><div class="col-12"><div class="course-card text-center"><h3 class="section-title">Courses (HSS)</h3><p><span>Select Programme:</span> <button class="course-btn active" data-target="#ug">UG Courses</button> <button class="course-btn" data-target="#foundation">Foundation Courses</button> <button class="course-btn" data-target="#pg">PG Courses</button></p></div></div></div><div class="row"><!-- LEFT PANEL --><div class="col-md-4"><!-- UG Courses --><div class="collapse show course-card course-group" id="ug"><h4>UG Courses</h4><p><button class="course-btn" data-pdf="/contents/hss/doc/ug_hss_2023-24.pdf">(2023-24)</button> <button class="course-btn" data-pdf="/contents/hss/doc/hss_ug_courses2020-21.pdf">(2020-21)</button> <button class="course-btn" data-pdf="/contents/hss/doc/dept_hss_list_of_ug_courses.xlsx.pdf">(2019-20)</button></p></div><!-- Foundation Courses --><div class="collapse course-card course-group" id="foundation"><h4>Foundation Courses</h4><p><button class="course-btn" data-pdf="/contents/hss/doc/foundation_hss_2023-24.pdf">(2020-21)</button></p></div><!-- PG Courses --><div class="collapse course-card course-group" id="pg"><h4>PG Courses</h4><p><button class="course-btn" data-pdf="/contents/hss/doc/phd_course_2023-24.pdf">PG Courses</button></p></div></div><!-- PDF VIEW --><div class="col-md-8"><div class="course-view"><iframe style="border:0;" id="pdfFrame" src="/contents/hss/doc/ug_hss_2023-24.pdf" width="100%" height="800"></iframe></div></div></div></div><!-- SCRIPT --><script>
        document.addEventListener("DOMContentLoaded", function () {
            const programButtons = document.querySelectorAll('[data-target]');
            const groups = document.querySelectorAll('.course-group');
            const pdfButtons = document.querySelectorAll('[data-pdf]');
            const frame = document.getElementById('pdfFrame');

            // Initialize Bootstrap Collapse manually
            const collapseMap = {};
            groups.forEach(g => {
                collapseMap[g.id] = new bootstrap.Collapse(g, { toggle: false });
            });

            // Program switch
            programButtons.forEach(btn => {
                btn.addEventListener('click', function () {
                    programButtons.forEach(b => b.classList.remove('active'));
                    this.classList.add('active');
                    Object.values(collapseMap).forEach(c => c.hide());
                    const targetId = this.getAttribute('data-target').replace('#','');
                    collapseMap[targetId].show();

                    // Auto-load first PDF in selected program
                    const firstPdfBtn = document.querySelector(`#${targetId} [data-pdf]`);
                    if(firstPdfBtn){
                        frame.src = firstPdfBtn.dataset.pdf;
                        pdfButtons.forEach(b => b.classList.remove('active'));
                        firstPdfBtn.classList.add('active');
                    }
                });
            });

            // PDF load
            pdfButtons.forEach(btn => {
                btn.addEventListener('click', function () {
                    frame.src = this.dataset.pdf;
                    pdfButtons.forEach(b => b.classList.remove('active'));
                    this.classList.add('active');
                });
            });
        });
    </script></div></div>
